mapper.select:
SELECT cd.*, p.name AS productName, p.cover_image AS productCoverImage, pt.title AS patternTitle, pt.image_url AS patternImageUrl, u.nickname AS userNickname FROM custom_design cd LEFT JOIN product p ON cd.product_id = p.id LEFT JOIN pattern pt ON cd.pattern_id = pt.id LEFT JOIN user u ON cd.user_id = u.id WHERE cd.deleted = 0
AND cd.user_id = #{userId}
AND cd.product_id = #{productId}
AND cd.status = #{status}
ORDER BY cd.created_at DESC
